const S = runtimeScene.__reigns;
if (!S.mod_datos) {
  S.mod_datos = true;
  S.data = {"finales":{"acad0":"Los profesores dejaron de creerte. Primero fue un paro de brazos caídos; después, las renuncias en cadena. Sin planta docente no hay clases, y sin clases no hay Unidad. El Consejo te pide el cargo.","acad100":"Tu planta docente lo puede todo: ya nada se mueve sin su visto bueno, ni un horario ni un presupuesto. La Unidad se volvió un gremio cerrado y el Consejo te retira por inmovilidad.","est0":"Los alumnos tomaron el edificio. Las aulas se vaciaron y la matrícula se desplomó. La noticia llegó a la prensa antes que a tu escritorio. Es el fin de tu gestión.","est100":"Quisiste complacer a todos los estudiantes y ya nada se pudo exigir. Bajó el rigor, cayó el prestigio y las acreditaciones quedaron en duda. El Consejo no pudo sostenerte.","fin0":"Se acabó el dinero. La nómina se atrasa, los proveedores no cobran y los apoyos no alcanzan. Sin caja no hay Unidad que dirigir, y el Consejo acepta tu renuncia.","fin100":"Guardaste tanto que la Unidad se quedó sin vida: sin becas, sin mantenimiento, sin ánimo. Alguien pidió una auditoría y las cuentas no cuadraron.","pol0":"Rectoría dejó de contestarte. Sin su respaldo, tus proyectos se quedaron en un cajón y tus enemigos aprovecharon. Te retiraron el cargo con una carta de dos líneas.","pol100":"Dijiste que sí a todo lo que bajaba de rectoría. La Unidad dejó de ser tuya: decisiones sin consultarte y tu gente sin voz. Terminaste firmando lo que otros decidieron.","epi_corrupto":"Te vas con favores que ya no podrás cobrar y deudas que no se ven en ningún libro. Alguien en rectoría ya anotó tu nombre.","epi_gris":"Te vas sin gloria ni vergüenza. Hiciste algunas cosas bien y otras por conveniencia, y la libreta de Mónica sigue con pendientes.","epi_integro":"Te vas con la cabeza en alto: quienes te conocen saben que dijiste la verdad aun cuando costaba.","derrota":"Las urnas hablaron: la comunidad prefirió a otra persona. Entregas las llaves y la historia de la Unidad sigue sin ti en la oficina.","retiro":"Decides no presentarte. Entregas las llaves, cierras el cajón y te vas al salón, que era lo que querías de joven.","limite":"El reglamento no te permite otro periodo. La comunidad se despide con aplausos tibios y un pastel de sábana.","epi_retiro":"Cierras la oficina y regresas al salón. Dar clases era lo único que no te pedía nada a cambio."},"finales_raros":{},"caidas":{},"destinos":[{"id":"integro","titulo":"Director íntegro","solo":true,"cierre":"Lo dices todo en el Consejo: el edificio, las minutas, los recibos y también los errores propios. No hay aplausos, pero tampoco miedo.","texto":"2040. La caída de Quintana abrió archivos que nadie quería abrir. La UAN perdió años y dinero, pero ganó algo raro: una auditoría que se hace sola cada semestre y un patronato nuevo con reglas escritas.","detalle":"En la Unidad de Economía todavía cuentan que {ant} fue quien preguntó. Mónica volvió a dar clases, y su libreta, completa, quedó en la biblioteca.","pj":"monica"},{"id":"unidad_primero","titulo":"La Unidad primero","solo":true,"cierre":"Expones a Quintana y callas el resto. La Unidad sigue en pie; tu conciencia, a medias.","texto":"2040. Quintana cayó solo, sin arrastrar a nadie más. Los cuatro siguen en sus puestos, más callados que antes. La UAN se recuperó sin escándalo, aunque con una pregunta que nadie vuelve a hacer.","detalle":"En Economía dicen que {ant} salvó a la Unidad. Otros dicen que salvó sus secretos. Los dos grupos tienen razón.","pj":"monica"},{"id":"heroica","titulo":"Caída con la frente en alto","solo":true,"cierre":"Peleas hasta el final y pierdes. El Consejo te retira el cargo, pero el expediente queda abierto.","texto":"2040. Años después, un periodista abrió tu expediente y encontró las preguntas que dejaste. Quintana alcanzó a retirarse, pero no a limpiar su apellido. La UAN tardó una década en entender lo que perdió ese día.","detalle":"{ant} dio clases en Economía hasta el final y nunca volvió a pedir un cargo. Mónica guardó su libreta junto a ese nombre.","pj":"director"},{"id":"sin_ti","titulo":"La Unidad sin ti","solo":true,"cierre":"Filtras todo, renuncias y te vas. Esa noche todo el estado sabe lo que pasó en el edificio.","texto":"2040. El escándalo derribó a Quintana, al Consejo y a medio patronato. La Unidad quedó en ruinas un tiempo y se reconstruyó sin ti, con otro nombre y reglas nuevas.","detalle":"Nadie en Economía sabe bien dónde terminó {ant}. Mónica asegura que, de vez en cuando, le llega una carta.","pj":"director"},{"id":"nuevo_quinto","titulo":"El nuevo Quinto","solo":true,"cierre":"Tomas su mano y su lugar. Desde esa noche, las decisiones de la Unidad salen de tu oficina... y de las sombras.","texto":"2040. La Unidad nunca tuvo tanto dinero ni tan pocas preguntas. Rectoría te cubre, los cuatro te obedecen y el edificio quemado dejó de aparecer en las minutas. En la UAN ya se dice que hay un Quinto.","detalle":"{ant} firma desde un despacho que antes era de otro. Cada tanto, alguien joven llega a preguntar algo en voz baja, y la historia empieza otra vez.","pj":"quintana"},{"id":"gris","titulo":"Sobrevivió","texto":"2040. La Unidad de Economía sobrevivió a varias rectorías y a demasiados directores. Nunca se supo del todo quién ordenó el incendio: la pregunta quedó escrita en una libreta.","detalle":"{ant} fue el último director de esta historia. El Quinto sigue siendo un nombre que nadie quiere decir en voz alta.","pj":"monica"}],"items":{},"mini":{},"uan":{"n_directores":8,"regresion":0.11,"nombres":{"solv":"Medidor 1","paz":"Medidor 2","aut":"Medidor 3","pre":"Medidor 4","des":"Medidor 5","seg":"Medidor 6"},"reeleccion":{"uan":[0,0,0,0],"nay":[0,0]},"epilogo":{"epi_integro":{"uan":[0,0,0,0],"nay":[0,0]},"epi_gris":{"uan":[0,0,0,0],"nay":[0,0]},"epi_corrupto":{"uan":[0,0,0,0],"nay":[0,0]},"epi_retiro":{"uan":[0,0,0,0],"nay":[0,0]}},"deriva":{"des":{"pre":0.1,"solv":0.06,"aut":0.04},"seg":{"paz":0.12,"aut":0.04}},"ex_inicial":{"id":"monica","nombre":"Mónica Salcedo","tono":"aliado"},"nombre_director":"Director","retrato_director":"director","metros":false,"actos":[{"id":"acto1","nombre":"Acto I · El hueco"},{"id":"acto2","nombre":"Acto II · Las manos","semmin":22},{"id":"acto3","nombre":"Acto III · El Quinto","req":["acto_quinto"]}]},"personajes":{"predecesor":"Predecesor","candidato":"Candidato","monica":"Mónica","janoe":"Janoe","sonia":"Sonia","perla":"Perla","ana":"Ana","edel":"Edel","victor":"Víctor","nayeli":"Nayeli","alfonso":"Alfonso","oscar":"Oscar Vizcaíno","sergio":"Sergio Olivares","martinez":"Martínez","gabriel":"Gabriel","beatriz":"Beatriz","roberto":"Roberto","norma":"Norma","juan":"Juan","oscar_alumno":"Oscar","jose":"José","director":"{dir}","quintana":"Aurelio Quintana"},"candidatos":[{"id":"cand_perla","pj":"perla","nombre":"Perla","rasgo":"tecnocrata","faccion":"investigadores","bonos":[6,0,2,-2],"fuerza":10,"favorece":{}},{"id":"cand_victor","pj":"victor","nombre":"Víctor","rasgo":"operador","faccion":"enlace con rectoría","bonos":[-2,0,0,6],"fuerza":10,"favorece":{}},{"id":"cand_nayeli","pj":"nayeli","nombre":"Nayeli","rasgo":"idealista","faccion":"nueva generación","bonos":[0,6,-2,0],"fuerza":10,"favorece":{}}],"cartas":[{"id":"u_equipos","pj":"janoe","texto":"Janoe necesita más equipos para Sistemas, pero la partida sólo alcanza para uno. ¿Lo asignas ya o esperas al cierre del semestre?","izq":{"t":"Asignarlo ya","e":[5,0,-6,0]},"der":{"t":"Esperar al cierre","e":[-4,0,4,0]},"unica":false},{"id":"u_horario","pj":"sonia","texto":"Dos profesores se pelearon por un horario. Sonia ya trajo café para los dos. ¿Resuelves tú o los dejas que lo arreglen?","izq":{"t":"Intervenir tú","e":[3,0,0,-2]},"der":{"t":"Dejar que lo arreglen","e":[-2,0,0,2]},"unica":false},{"id":"u_kermes","pj":"nayeli","texto":"Los alumnos organizan una kermés para juntar fondos. Nayeli pide permiso y, de paso, el auditorio.","izq":{"t":"Autorizarla","e":[0,8,3,-2]},"der":{"t":"Negarla por el riesgo","e":[0,-6,0,3]},"unica":false},{"id":"u_pumas","pj":"alfonso","texto":"Alfonso pide el auditorio para ver el partido de los Pumas. 'Es por la cohesión del equipo', jura con la mano en el pecho.","izq":{"t":"Autorizar el partido","e":[3,4,-2,0]},"der":{"t":"Negar con una sonrisa","e":[-2,0,1,1]},"unica":false,"peso":0.8},{"id":"u_servidor","pj":"gabriel","texto":"El servidor de la Unidad murió. Gabriel dice que lo revive con 'piezas de otros equipos'. Rectoría tardaría meses en mandar uno.","izq":{"t":"Que Gabriel lo reviva","e":[4,2,-3,0]},"der":{"t":"Pedir uno nuevo a rectoría","e":[0,0,0,-6]},"unica":false},{"id":"u_beatriz","pj":"beatriz","texto":"Un grupo se queja de que Beatriz es demasiado estricta. Ella afirma que sus alumnos aprenden. Tú decides de qué lado estar.","izq":{"t":"Respaldar a Beatriz","e":[5,-6,0,0]},"der":{"t":"Pedirle que flexibilice","e":[-5,6,0,0]},"unica":false},{"id":"u_martinez","pj":"martinez","texto":"Martínez no quiere presentar su proyecto ante la junta: le dan pánico los micrófonos. Dice que lo manda por correo.","izq":{"t":"Acompañarlo al frente","e":[4,0,0,-1]},"der":{"t":"Aceptar el correo","e":[1,0,1,0]},"unica":false},{"id":"u_roberto","pj":"roberto","texto":"Roberto te atrapa en el pasillo con una historia de 1998. Se le pierde el hilo, pero parece que hay una buena idea escondida.","izq":{"t":"Escucharlo hasta el final","e":[3,0,-1,0]},"der":{"t":"Prometer una cita larga","e":[0,0,1,0]},"unica":false},{"id":"u_oscar","pj":"oscar","texto":"Oscar propone dar economía con simulaciones de mercado en vivo, usando dados. 'Va a funcionar', dice. Parece que lo cree.","izq":{"t":"Probarla un semestre","e":[3,5,-3,0]},"der":{"t":"Posponerla","e":[-2,-2,1,1]},"unica":false},{"id":"u_torneo","pj":"sergio","texto":"Sergio Olivares propone un torneo de rol con cosplay obligatorio para juntar fondos. 'Estrictamente recomendable', dice, con total seriedad.","izq":{"t":"Aprobar la campaña","e":[2,9,5,-5],"set":["torneo_rol"]},"der":{"t":"Decir que no hay presupuesto","e":[0,-3,0,2]},"unica":true},{"id":"j1","pj":"jose","texto":"José pide hablar a solas. No alza la voz: nunca la alza. Dice que el gremio está dividido y que solo él puede unirlo... si lo nombras coordinador del comité de planeación.","izq":{"t":"Nombrarlo coordinador","e":[7,0,0,2],"set":["jose_coordina"],"luego":{"semanas":2,"carta":"j2"}},"der":{"t":"Dejar el comité como está","e":[-5,0,0,0],"luego":{"semanas":2,"carta":"j2"}},"semmin":28,"peso":3,"unica":true,"cadena":"jose"},{"id":"j2","pj":"jose","texto":"El comité se reúne y José ya traía el calendario, los acuerdos y hasta las minutas. Cada propuesta suya pasa. Perla frunce el ceño: «Aquí ya no se discute nada».","izq":{"t":"Dejar que avance","e":[6,0,2,0],"set":["jose_cedes"],"luego":{"semanas":2,"carta":"j3"}},"der":{"t":"Exigir debate abierto","e":[-5,0,0,0],"int":3,"set":["jose_resistes"],"luego":{"semanas":2,"carta":"j3"}},"solo_luego":true,"unica":true,"cadena":"jose"},{"id":"j3","pj":"jose","texto":"José te cita en tu oficina: «Hay votación por la plantilla. Con mi lista, el recorte no te toca. Sin ella, habrá paro en dos semanas». Lo dice como quien comenta el clima.","izq":{"t":"Aceptar su lista","e":[8,0,-6,0],"luego":{"semanas":2,"carta":"j4a"}},"der":{"t":"Plantarle cara","e":[-8,0,3,0],"luego":{"semanas":2,"carta":"j4b"}},"solo_luego":true,"unica":true,"cadena":"jose"},{"id":"j4a","pj":"jose","texto":"La lista pasa. Una semana después descubres que protege a quienes él quiere y deja fuera a quienes le estorban, incluidos dos profesores que confiaban en ti. El gremio ahora es suyo. Y tú, su aval.","izq":{"t":"Aceptarlo como el costo","e":[4,0,0,-3],"int":-8,"set":["jose_fin","jose_gano"]},"der":{"t":"Revisar la lista y corregirla","e":[-4,0,-2,0],"int":6,"set":["jose_fin"]},"solo_luego":true,"unica":true,"cadena":"jose"},{"id":"j4b","pj":"jose","texto":"José no levanta la voz: convoca a una asamblea de profesores y deja que otros hablen por él. Dos días después, el paro está votado. «Nada personal», murmura al salir.","izq":{"t":"Negociar con el gremio entero","e":[6,0,-6,-2],"set":["jose_fin","jose_negocia"]},"der":{"t":"Aguantar el paro","e":[-12,-4,5,3],"int":2,"set":["jose_fin"]},"solo_luego":true,"unica":true,"cadena":"jose"},{"id":"u1","pj":"juan","texto":"Juan, el contador de siempre, aparece con una carpeta delgada. «Vi que Ana revisó los libros de antes. Cuidado: tocar eso puede quemarte. Yo puedo ordenarlo todo, de modo que nadie se queme».","izq":{"t":"Dejar que Juan ordene","e":[0,0,6,2],"int":-4,"set":["juan_ordena"],"luego":{"semanas":2,"carta":"u2"}},"der":{"t":"Que Ana siga con su revisión","e":[0,0,-4,0],"int":4,"set":["ana_sigue"],"luego":{"semanas":2,"carta":"u2"}},"semmin":32,"peso":3,"unica":true,"cadena":"juan"},{"id":"u2","pj":"juan","texto":"Juan te muestra un balance impecable: el hueco casi desaparece. Demasiado limpio. Ana susurra: «Cuadra porque falta un renglón. Hay cajas que nunca se contaron».","izq":{"t":"Aprobar el balance limpio","e":[0,0,10,3],"int":-8,"set":["juan_cedes"],"luego":{"semanas":2,"carta":"u3"}},"der":{"t":"Exigir el renglón faltante","e":[0,0,-5,0],"int":4,"set":["juan_resistes"],"luego":{"semanas":2,"carta":"u3"}},"solo_luego":true,"unica":true,"cadena":"juan"},{"id":"u3","pj":"juan","texto":"Una noche, Juan te espera en la oficina. «El edificio ardió una vez y todos prefirieron no preguntar. Tú también puedes preferirlo». No es una amenaza. Es peor: parece un consejo.","izq":{"t":"Preguntar por las cajas","e":[0,0,-3,-3],"luego":{"semanas":2,"carta":"u4a"}},"der":{"t":"Fingir que no lo oíste","e":[0,0,3,3],"int":-6,"luego":{"semanas":2,"carta":"u4b"}},"solo_luego":true,"unica":true,"cadena":"juan"},{"id":"u4a","pj":"juan","texto":"Juan se queda en silencio. Luego abre su carpeta: copias de recibos de antes del incendio. «No son todos. Son los que sobrevivieron». Te los da. O finge que te los da.","izq":{"t":"Guardarlos y seguir el rastro","e":[0,0,-4,0],"int":10,"set":["juan_fin","juan_pistas"]},"der":{"t":"Devolvérselos y cerrar el tema","e":[0,0,4,2],"int":-6,"set":["juan_fin"]},"solo_luego":true,"unica":true,"cadena":"juan"},{"id":"u4b","pj":"juan","texto":"Las cuentas cierran en paz. Demasiada paz. Ana renuncia sin explicar y deja una nota sobre tu escritorio: «Ya sabes quién lleva los libros».","izq":{"t":"Dejarla ir","e":[0,0,5,3],"int":-8,"set":["juan_fin","juan_gano"]},"der":{"t":"Rogarle que se quede","e":[-2,0,-3,0],"int":3,"set":["juan_fin","ana_se_queda"]},"solo_luego":true,"unica":true,"cadena":"juan"},{"id":"n1","pj":"norma","texto":"Norma llega sin cita y con pastel: «Para los directores nuevos, siempre algo dulce». Pregunta por tu convenio, tus pendientes, tus decisiones. Sonríe tanto que no sabes cuánta información ya trae.","izq":{"t":"Compartirle tus planes","e":[0,0,4,6],"set":["norma_confias"],"luego":{"semanas":2,"carta":"n2"}},"der":{"t":"Agradecer y guardar silencio","e":[0,0,0,-5],"luego":{"semanas":2,"carta":"n2"}},"semmin":36,"peso":3,"unica":true,"cadena":"norma"},{"id":"n2","pj":"norma","texto":"Norma te ofrece un fondo extraordinario «para que la Unidad respire». Viene con una condición discreta: un nombre en tu comité de adquisiciones. «Alguien de mi confianza».","izq":{"t":"Aceptar el fondo y el nombre","e":[0,0,12,8],"int":-8,"set":["norma_cedes"],"luego":{"semanas":2,"carta":"n3"}},"der":{"t":"Aceptar el fondo sin el nombre","e":[0,0,3,-8],"int":3,"set":["norma_resistes"],"luego":{"semanas":2,"carta":"n3"}},"solo_luego":true,"unica":true,"cadena":"norma"},{"id":"n3","pj":"norma","texto":"Sin aviso, rectoría cambia las reglas del subsidio. Norma lo lamenta por teléfono, con voz dulce: «Son decisiones de arriba. Pero tú y yo podemos arreglar esto, ¿verdad?».","izq":{"t":"Buscar un acuerdo con ella","e":[0,0,4,6],"luego":{"semanas":2,"carta":"n4a"}},"der":{"t":"Ir al Consejo con las pruebas","e":[3,0,-5,-8],"luego":{"semanas":2,"carta":"n4b"}},"solo_luego":true,"unica":true,"cadena":"norma"},{"id":"n4a","pj":"norma","texto":"El acuerdo llega con un precio: una carta pública de respaldo a su gestión. Te la dan ya redactada, con tu firma pendiente. «Un detalle sin importancia».","izq":{"t":"Firmar la carta","e":[0,0,8,10],"int":-12,"set":["norma_fin","norma_gano"]},"der":{"t":"Reescribirla con tus palabras","e":[0,0,-2,-6],"int":5,"set":["norma_fin"]},"solo_luego":true,"unica":true,"cadena":"norma"},{"id":"n4b","pj":"norma","texto":"Frente al Consejo, el asunto se hace público. Norma no se defiende: sonríe y toma nota. Al salir te dice: «Me gusta la gente con carácter. Aunque a veces se rompe».","izq":{"t":"Sostener tu postura","e":[4,3,-4,-12],"int":8,"set":["norma_fin","norma_enemiga"]},"der":{"t":"Bajar el tono","e":[0,0,2,2],"int":-4,"set":["norma_fin"]},"solo_luego":true,"unica":true,"cadena":"norma"},{"id":"o1","pj":"oscar_alumno","texto":"Oscar convoca a los alumnos en el patio. Dice que la Unidad les debe respuestas y que él las va a conseguir. Desde la asamblea es el más escuchado. Quiere que apoyes su pliego petitorio.","izq":{"t":"Recibir a la comisión estudiantil","e":[0,8,-3,-2],"set":["oscar_pliego"],"luego":{"semanas":2,"carta":"o2"}},"der":{"t":"Pedir que pasen por ventanilla","e":[0,-7,0,3],"luego":{"semanas":2,"carta":"o2"}},"semmin":24,"peso":3,"unica":true,"cadena":"oscar"},{"id":"o2","pj":"oscar_alumno","texto":"Oscar te presenta el pliego: becas ampliadas, comedor gratuito y «voz y voto» en el presupuesto. Suena justo. También suena imposible. A su alrededor, todos aplauden antes de que respondas.","izq":{"t":"Aceptar casi todo","e":[-3,12,-12,-2],"set":["oscar_cedes"],"luego":{"semanas":2,"carta":"o3"}},"der":{"t":"Aceptar solo lo posible","e":[0,-6,2,0],"set":["oscar_resistes"],"luego":{"semanas":2,"carta":"o3"}},"solo_luego":true,"unica":true,"cadena":"oscar"},{"id":"o3","pj":"oscar_alumno","texto":"Oscar sonríe frente al micrófono: «El director cumplió... a medias». El patio se calienta. Alguien propone tomar la dirección «solo por unas horas». Oscar no lo detiene. Tampoco lo apoya. Espera.","izq":{"t":"Salir a hablar frente a todos","e":[0,4,0,-3],"luego":{"semanas":2,"carta":"o4a"}},"der":{"t":"Pedir que rectoría intervenga","e":[0,-10,0,6],"luego":{"semanas":2,"carta":"o4b"}},"solo_luego":true,"unica":true,"cadena":"oscar"},{"id":"o4a","pj":"oscar_alumno","texto":"Hablas ante el patio. Oscar te reta con una pregunta que no puedes esquivar: «¿De dónde saldría el dinero?». Todos esperan. Aquí te cuestionan mejor que en cualquier junta.","izq":{"t":"Decir la verdad: no alcanza","e":[0,-4,4,0],"int":8,"set":["oscar_fin","oscar_verdad"]},"der":{"t":"Prometer lo que él pide","e":[0,10,-10,0],"int":-10,"set":["oscar_fin","oscar_gano"]},"solo_luego":true,"unica":true,"cadena":"oscar"},{"id":"o4b","pj":"oscar_alumno","texto":"Con rectoría de testigo se evita la toma... a cambio de un acta que te compromete a «mantener el orden». Oscar se retira tranquilo: acaba de ganar algo que tú todavía no ves.","izq":{"t":"Firmar el acta","e":[0,-6,2,8],"set":["oscar_fin","oscar_acta"]},"der":{"t":"Rechazarla","e":[0,-3,0,-6],"int":4,"set":["oscar_fin"]},"solo_luego":true,"unica":true,"cadena":"oscar"},{"id":"pend_1","pj":"monica","texto":"En la libreta de Mónica, pendiente 1: «La nómina de diciembre». Después del fallo de la Corte faltan fondos para completarla. Puedes pedirle un adelanto a rectoría... o recortar dentro de la Unidad.","izq":{"t":"Pedir un adelanto a rectoría","e":[0,0,8,-10],"set":["debe_a_rectoria"],"luego":{"semanas":3,"carta":"pend_2"}},"der":{"t":"Recortar gastos de la Unidad","e":[-8,-3,10,0],"set":["recorte_inicial"],"luego":{"semanas":3,"carta":"pend_2"}},"cadena":"pendientes","semana":0,"unica":true},{"id":"pend_2","pj":"sonia","texto":"En la libreta de Mónica, pendiente 2: «Los alumnos». Se corrió la voz del hueco y exigen una asamblea. Sonia se ofrece a mediar, pero alguien tiene que dar la cara.","izq":{"t":"Dar la cara en la asamblea","e":[0,9,-2,-4],"int":3,"luego":{"semanas":3,"carta":"pend_3"}},"der":{"t":"Que Sonia lo maneje","e":[0,-4,0,3],"luego":{"semanas":3,"carta":"pend_3"}},"cadena":"pendientes","solo_luego":true,"unica":true},{"id":"pend_3","pj":"perla","texto":"En la libreta de Mónica, pendiente 3: «El gremio». Perla, líder de los profesores, pide garantías de contrato antes de aceptar un solo recorte más. Si no las firmas, habla de paro.","izq":{"t":"Firmar las garantías","e":[10,0,-8,-3],"set":["garantias_firmadas"],"luego":{"semanas":3,"carta":"pend_4"}},"der":{"t":"Prometer sin firmar","e":[4,0,0,0],"int":-6,"set":["promesa_vacia"],"luego":{"semanas":3,"carta":"pend_4"}},"cadena":"pendientes","solo_luego":true,"unica":true},{"id":"pend_4","pj":"ana","texto":"En la libreta de Mónica, pendiente 4: «Las cuentas». Ana revisó el ejercicio anterior y hay una errata enorme: gastos sin comprobante, cifras que no cuadran. Nadie en el edificio quiere hablar de eso.","izq":{"t":"Que siga, en silencio","e":[0,0,-3,0],"int":4,"set":["hallazgo_cuentas"],"luego":{"semanas":3,"carta":"pend_5"}},"der":{"t":"Archivarlo: hay incendios más urgentes","e":[0,0,3,4],"int":-8,"set":["archivo_cerrado"],"luego":{"semanas":3,"carta":"pend_5"}},"cadena":"pendientes","solo_luego":true,"unica":true},{"id":"pend_5","pj":"edel","texto":"En la libreta de Mónica, pendiente 5: «El archivo muerto». Edel llegó temprano y encontró forzada la bodega del edificio de Finanzas, el que se quemó. Faltan cajas con papeles.","izq":{"t":"Denunciarlo ante rectoría","e":[0,0,0,-6],"int":5,"set":["denuncia_archivo"],"luego":{"semanas":3,"carta":"pend_6"}},"der":{"t":"Investigarlo tú mismo","e":[0,0,-4,0],"set":["investigas_archivo"],"luego":{"semanas":3,"carta":"pend_6"}},"cadena":"pendientes","solo_luego":true,"unica":true},{"id":"pend_6","pj":"victor","texto":"En la libreta de Mónica, pendiente 6: «Rectoría». Víctor llega sonriendo con una carta: el apoyo de rectoría será total... con una condición. Tu firma en un convenio que no te dejaron leer completo.","izq":{"t":"Firmar: necesitas el dinero","e":[0,0,12,8],"int":-10,"set":["firmaste_convenio"],"luego":{"semanas":4,"carta":"pend_7"}},"der":{"t":"Pedir tiempo para leerlo","e":[0,0,-4,-8],"int":4,"set":["leiste_convenio"],"luego":{"semanas":4,"carta":"pend_7"}},"cadena":"pendientes","solo_luego":true,"unica":true},{"id":"pend_7","pj":"monica","texto":"El pendiente 7 está sellado. Mónica llama justo ahora: «No lo abras todavía. Cuando cuatro personas te hayan ofrecido ayuda, vas a entender por qué me fui. Aprende a desconfiar de la ayuda».","izq":{"t":"Abrirlo ahora","e":[0,0,0,-4],"int":2,"set":["abriste_pendiente_7"]},"der":{"t":"Esperar a estar listo","e":[0,0,0,0],"set":["esperas_pendiente_7"]},"cadena":"pendientes","solo_luego":true,"unica":true},{"id":"r1","pj":"monica","texto":"Mónica aparece sin avisar, empapada de lluvia. «Ya sé lo que encontré. Los cuatro aparecen en las minutas del edificio que se quemó, pero ninguno firma. Alguien más daba las órdenes. Lo llamaban “el Quinto”».","izq":{"t":"Escucharla completa","e":[0,0,0,0],"int":4,"luego":{"semanas":1,"carta":"r2"},"set":["acto_quinto"]},"der":{"t":"Exigir pruebas primero","e":[0,0,0,0],"luego":{"semanas":1,"carta":"r2"},"set":["acto_quinto"]},"req":["oscar_fin","jose_fin","juan_fin","norma_fin"],"semmin":44,"peso":6,"unica":true,"cadena":"quintana"},{"id":"r2","pj":"monica","texto":"Mónica por fin te entrega el pendiente 7, el sellado. Trae un nombre: Aurelio Quintana, el quinto director de la Unidad. «Me obligó a renunciar. Yo sabía lo del incendio y callé por miedo. Sé que me debes un reproche».","izq":{"t":"Perdonarla, pero exigir toda la verdad","e":[0,0,0,0],"int":3,"af":{"monica":1},"set":["mon_perdon"],"luego":{"semanas":3,"carta":"q1"}},"der":{"t":"Reprocharle haber callado","e":[0,0,0,0],"int":2,"af":{"monica":-1},"set":["mon_reproche"],"luego":{"semanas":3,"carta":"q1"}},"solo_luego":true,"unica":true,"cadena":"quintana"},{"id":"q1","pj":"quintana","texto":"Un hombre de saco azul entra a tu oficina con dos cafés. «Aurelio Quintana. Fui el quinto director de esta Unidad; me dicen “el Quinto”. Mónica te habló de mí, me imagino. No creas todo lo que se cuenta en los pasillos».","izq":{"t":"Aceptar el café y escucharlo","e":[0,0,0,3],"int":-3,"set":["q_cafe"],"luego":{"semanas":3,"carta":"q2"}},"der":{"t":"Decirle que sabes lo que hizo","e":[0,0,0,-6],"int":4,"set":["q_enfrentas"],"luego":{"semanas":3,"carta":"q2"}},"cadena":"quintana","unica":true,"solo_luego":true},{"id":"q2","pj":"norma","texto":"Los cuatro entran juntos y se sientan sin que nadie los invite. Nadie niega nada. Norma habla con calma: «Quintana nos pidió ayudarte... y vigilarte. Si hablamos, ¿quién nos protege de él?».","izq":{"t":"Pedirles que testifiquen","e":[-3,-3,-3,-5],"int":6,"set":["cuatro_testifican"],"luego":{"semanas":4,"carta":"q3"}},"der":{"t":"Dejarlos como tus ojos dentro","e":[3,3,3,3],"int":-3,"set":["cuatro_ojos"],"luego":{"semanas":4,"carta":"q3"}},"cadena":"quintana","unica":true,"solo_luego":true},{"id":"q3","pj":"quintana","texto":"Una auditoría llega al Consejo con tu firma en los recibos del edificio quemado. Quintana pasa por tu oficina: «Es una pena. Yo puedo hacerla desaparecer, con una sola condición: que dejes de buscar». Te da una semana.","izq":{"t":"Rechazar y pedir auditoría externa","e":[0,0,-4,-6],"int":6,"set":["q_ultimatum","q_audit"],"luego":{"semanas":8,"carta":"f1"}},"der":{"t":"Pedir tiempo y negociar","e":[0,0,4,4],"int":-6,"set":["q_ultimatum","q_negocias"],"luego":{"semanas":8,"carta":"f1"}},"cadena":"quintana","unica":true,"solo_luego":true},{"id":"t_juan","pj":"juan","texto":"Juan llega con la carpeta que le guardaste. «Faltaba la hoja que Quintana arrancó. La conservé porque nadie la pidió». Es la prueba de que las órdenes del edificio no salieron de ti.","izq":{"t":"Guardarla para el momento justo","e":[0,0,2,0],"int":4,"set":["prueba_juan"]},"der":{"t":"Presentarla ya ante la auditoría","e":[0,0,-3,3],"int":6,"set":["prueba_juan"]},"cadena":"quintana","unica":true,"req":["q_ultimatum","juan_pistas"],"noreq":[],"peso":8},{"id":"t_oscar","pj":"oscar_alumno","texto":"Oscar convoca al patio otra vez, pero ahora a tu favor: «El director nos dijo que no alcanzaba. Fue el único que no nos mintió». Piden una auditoría pública y firman por ti.","izq":{"t":"Aceptar su apoyo","e":[0,10,0,-3],"int":3,"set":["prueba_oscar"]},"der":{"t":"Pedirles que no se expongan","e":[0,-3,0,3],"int":4,"set":["prueba_oscar"]},"cadena":"quintana","unica":true,"req":["q_ultimatum","oscar_verdad"],"noreq":[],"peso":8},{"id":"t_jose","pj":"jose","texto":"José, sin alzar la voz, te pasa una carta con cuarenta firmas de profesores: «No es política. Es que ya vimos quién maneja los hilos». Solo falta decidir cuándo usarla.","izq":{"t":"Usarla ahora","e":[8,0,0,-4],"int":3,"set":["prueba_jose"]},"der":{"t":"Guardarla de reserva","e":[3,0,0,0],"int":3,"set":["prueba_jose"]},"cadena":"quintana","unica":true,"req":["q_ultimatum","jose_negocia"],"noreq":[],"peso":8},{"id":"t_norma","pj":"norma","texto":"Norma te llama de noche. Su voz ya no es dulce: «Quintana me prometió rectoría y me dejó las manos sucias. Te daré las actas del Consejo si me prometes dejarme fuera».","izq":{"t":"Aceptar su trato","e":[0,0,0,6],"int":-3,"set":["prueba_norma"]},"der":{"t":"No prometer nada: pedir las actas","e":[0,0,-2,-4],"int":5,"set":["prueba_norma"]},"cadena":"quintana","unica":true,"req":["q_ultimatum","norma_fin"],"noreq":["norma_gano"],"peso":8},{"id":"q_cobro","pj":"quintana","texto":"Quintana revisa lo que concediste: «Veo que ya entendiste cómo funciona esto, director. Nada personal: un favor de tu parte cuando llegue el momento, y la auditoría se archiva».","izq":{"t":"Dejarle lo que pide","e":[0,0,8,8],"int":-8,"set":["q_debes"]},"der":{"t":"Plantarte tarde, pero plantarte","e":[0,0,-6,-6],"int":6,"set":["q_firme"]},"cadena":"quintana","unica":true,"req":["q_ultimatum","q_negocias"],"noreq":[],"peso":8},{"id":"f1","pj":"quintana","texto":"Quintana ya no sonríe del todo. «Siempre ha habido un Quinto. Antes de mí hubo otro, y habrá otro después. Quiero que seas tú: dinero, rectoría de tu lado y los cuatro obedeciendo. Solo tienes que dejar de preguntar».","izq":{"t":"Aceptar su lugar","e":[6,6,10,10],"int":-20,"set":["final_quinto"],"destino":"nuevo_quinto"},"der":{"t":"Rechazarlo","e":[0,0,0,-4],"int":4,"luego":{"semanas":1,"carta":"f2"}},"cadena":"quintana","unica":true,"solo_luego":true},{"id":"f2","pj":"monica","texto":"Mónica sabe que lo rechazaste. «Hoy sesiona el Consejo. Puedes exponerlo con lo que tengas, o soltarlo todo a la prensa y renunciar: él cae, pero la Unidad se sacude y tú te vas. ¿Cómo lo derribas?».","izq":{"t":"Exponerlo ante el Consejo","e":[0,0,0,-4],"set":["q_expone"]},"der":{"t":"Filtrar todo y renunciar","e":[-6,-6,-6,-6],"int":5,"destino":"sin_ti"},"cadena":"quintana","unica":true,"solo_luego":true},{"id":"f_ok","pj":"quintana","texto":"El Consejo escucha. Con las pruebas de los tuyos, Quintana no encuentra salida, pero aún sonríe: «Te va a pesar, director». Ahora decides cuánta verdad sale de esta sala.","izq":{"t":"Decirlo todo, errores de la Unidad incluidos","e":[0,0,-6,-6],"int":10,"destino":"integro"},"der":{"t":"Exponer solo a Quintana y cuidar a los tuyos","e":[4,4,4,0],"int":-4,"destino":"unidad_primero"},"cadena":"quintana","unica":true,"req":["q_expone"],"si":{"int":">=60"},"peso":99},{"id":"f_mal","pj":"quintana","texto":"Sin pruebas suficientes, el Consejo duda de ti. Quintana muestra tu firma en los recibos, tranquilo: «Lamento esto, director». Todavía puedes pelear hasta el final... o tomar su mano.","izq":{"t":"Defenderte hasta el final","e":[0,0,0,-8],"int":8,"destino":"heroica"},"der":{"t":"Tomar su mano ahora","e":[4,4,6,6],"int":-15,"set":["final_quinto"],"destino":"nuevo_quinto"},"cadena":"quintana","unica":true,"req":["q_expone"],"si":{"int":"<60"},"peso":99},{"id":"yo_1","pj":"director","texto":"Te quedas solo en la oficina. La libreta de Mónica sigue abierta sobre el escritorio. Te preguntas quién serás en esta historia: quien salva la Unidad o quien logra sobrevivirla.","izq":{"t":"Salvarla, cueste lo que cueste","e":[0,0,-3,0],"set":["perfil_salvador"],"luego":{"semanas":6,"carta":"yo_2"}},"der":{"t":"Sobrevivir primero","e":[0,0,3,3],"set":["perfil_superviviente"],"luego":{"semanas":6,"carta":"yo_2"}},"cadena":"tu_camino","semmin":8,"peso":3,"unica":true},{"id":"yo_2","pj":"director","texto":"Tu nombre empieza a sonar en los pasillos. Algunos dicen que lo estás haciendo bien; otros, que te falta carácter. ¿Buscarás un segundo periodo cuando llegue la elección?","izq":{"t":"Sí: me presentaré a la reelección","e":[0,0,0,-2],"fe":2,"set":["quieres_reeleccion"]},"der":{"t":"Aún no lo sé","e":[0,0,0,0],"set":["indeciso_reeleccion"]},"cadena":"tu_camino","solo_luego":true,"unica":true},{"id":"yo_campana","pj":"director","texto":"Tu equipo te pide un lema para la campaña. Dos ideas se pelean sobre la mesa: «Sigamos» o «Hagámoslo distinto».","izq":{"t":"Continuidad: «Sigamos»","e":[0,0,0,2],"fe":1,"voto":{"prof":3,"cons":2}},"der":{"t":"Cambio: «Hagámoslo distinto»","e":[0,0,0,-1],"fe":1,"voto":{"est":3,"trab":2}},"cadena":"tu_camino","campana":true,"unica":true},{"id":"yo_reelecto","pj":"director","texto":"Ganaste el segundo periodo. Los que dudaban de ti ahora te miran distinto, y los que te apoyaron esperan que cumplas. Ya no eres la persona que recibió las llaves de Mónica.","izq":{"t":"Gobernar con más firmeza","e":[0,0,0,4],"int":-2},"der":{"t":"Tender la mano a los críticos","e":[2,2,0,-2],"int":3},"cadena":"tu_camino","reelmin":1,"unica":true}],"roles":{"alejandro":"aliado","beatriz":"aliado","fernando":"aliado","janoe":"aliado","monica":"anfitriona","nayeli":"aliado","sergio":"aliado","sonia":"aliado","victor":"aliado","alfonso":"aliado","angel":"aliado","carlos":"aliado","eligardo":"aliado","gabriel":"aliado","perla":"aliado","jose_19":"aliado","raudel":"aliado","roberto":"aliado","oscar":"aliado","martinez":"aliado","oliver":"aliado","lugo":"aliado","jose_25":"aliado","ricardo":"aliado","j