  P.tomar = function () {
    let p = P.libres.pop();
    if (p) return p;
    if (P.total >= MAX) return null;            // limite global: nunca se crean mas de MAX objetos Particula
    let o = null;
    try { o = runtimeScene.createObject("Particula"); } catch (e) { return null; }
    if (!o) return null;
    P.total++;
    return { o };
  };
  P.liberar = function (p) {
    try { p.o.hide(true); } catch (e) { }
